import { createSelector } from "@reduxjs/toolkit";
import { baseNavigationPages } from "../reducers/navigationReducer";
import { NavigationPage } from "../types/general/NavigationState";
import { RootState } from "../store/store";
import { PAGE_SLUGS } from "../constants/pageSlugs";

const selectAccessControlState = (state: RootState) => state.accessControl;
const selectSessionState = (state: RootState) => state.session;

const VOLUNTEER_PROGRESS_MANAGEMENT_ROLES = new Set([
  "owner",
  "admin",
  "manager",
  "assistant-manager",
]);

const normalizeRoleSlug = (roleSlug: string | null | undefined): string => {
  const normalized = String(roleSlug ?? "").trim().toLowerCase().replace(/[\s_]+/g, "-");
  const collapsed = normalized.replace(/-/g, "");
  if (collapsed === "administrator") return "admin";
  if (collapsed === "assistantmanager" || collapsed === "assistmanager") return "assistant-manager";
  return normalized;
};

export const canShowVolunteerProgressNavigation = (
  roleSlug: string | null | undefined,
  staffType: string | null | undefined,
): boolean =>
  VOLUNTEER_PROGRESS_MANAGEMENT_ROLES.has(normalizeRoleSlug(roleSlug)) ||
  String(staffType ?? "").trim().toLowerCase() === "volunteer";

const MODULE_SLUG_TO_PAGE_SLUG: Record<string, string> = {
  "am-task-management": PAGE_SLUGS.assistantManagerTasks,
};

const PAGE_SLUG_ALIASES: Record<string, string[]> = {
  [PAGE_SLUGS.reports]: [PAGE_SLUGS.openBarControl],
  [PAGE_SLUGS.settingsPermissions]: [
    PAGE_SLUGS.settingsPages,
    PAGE_SLUGS.settingsModules,
    PAGE_SLUGS.settingsPagePermissions,
    PAGE_SLUGS.settingsModulePermissions,
  ],
  [PAGE_SLUGS.settingsPages]: [PAGE_SLUGS.settingsPermissions],
  [PAGE_SLUGS.settingsModules]: [PAGE_SLUGS.settingsPermissions],
  [PAGE_SLUGS.settingsPagePermissions]: [PAGE_SLUGS.settingsPermissions],
  [PAGE_SLUGS.settingsModulePermissions]: [PAGE_SLUGS.settingsPermissions],
  [PAGE_SLUGS.settingsControlPanel]: [PAGE_SLUGS.settingsGoogleApi],
  [PAGE_SLUGS.settingsGoogleApi]: [PAGE_SLUGS.settingsControlPanel],
  [PAGE_SLUGS.marketing]: [PAGE_SLUGS.searchConsole],
  [PAGE_SLUGS.searchConsole]: [PAGE_SLUGS.marketing],
};

export const selectAllowedPageSlugs = createSelector(selectAccessControlState, ({ pages, modules }) => {
  const allowedSlugs = new Set(pages);

  pages.forEach((pageSlug) => {
    const aliases = PAGE_SLUG_ALIASES[pageSlug];
    if (!aliases) {
      return;
    }
    aliases.forEach((alias) => allowedSlugs.add(alias));
  });

  Object.keys(modules).forEach((moduleSlug) => {
    const mappedPageSlug = MODULE_SLUG_TO_PAGE_SLUG[moduleSlug];
    if (mappedPageSlug) {
      allowedSlugs.add(mappedPageSlug);
    }
  });

  return allowedSlugs;
});

export const selectAllowedNavigationPages = createSelector(
  selectAccessControlState,
  selectAllowedPageSlugs,
  selectSessionState,
  ({ loaded }, allowedSlugs, session): NavigationPage[] => {
    if (!loaded) {
      return [];
    }

    return baseNavigationPages.filter(
      (page) =>
        allowedSlugs.has(page.slug) &&
        (page.slug !== PAGE_SLUGS.volunteerProgress ||
          canShowVolunteerProgressNavigation(session.roleSlug, session.staffType)),
    );
  },
);

export const selectModulePermissionsMap = createSelector(selectAccessControlState, ({ modules }) => {
  const permissionMap = new Map<string, Set<string>>();

  Object.entries(modules).forEach(([moduleSlug, actions]) => {
    permissionMap.set(moduleSlug, new Set(actions));
  });

  return permissionMap;
});

export const makeSelectIsPageAllowed = (pageSlug: string) =>
  createSelector(selectAllowedPageSlugs, (allowedSlugs) => allowedSlugs.has(pageSlug));

export const makeSelectIsModuleActionAllowed = (moduleSlug: string, actionKey: string) =>
  createSelector(selectModulePermissionsMap, (permissionMap) =>
    permissionMap.get(moduleSlug)?.has(actionKey) ?? false,
  );
